(()=>{
'use strict';
let active=null,checking=false;
const en=()=>document.documentElement.lang==='en';
const t=(he,english)=>en()?english:he;
const visible=el=>el&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden';
const steps=[
 ['#dashboard-title','ברוכים הבאים לאזור האישי','Welcome to your account','כאן מרוכזים ההשאלות, הפריטים והגמ״חים שלך. נכיר יחד את המקומות החשובים.','Your loans, items and gmachs live here. Let’s take a quick look around.'],
 ['[data-dashboard-tab="requests"]','כל ההשאלות במקום אחד','All your loans in one place','כאן עוקבים אחר בקשות, אישורים, מועדי איסוף והחזרה. כשנדרשת פעולה שלך, היא תופיע כאן.','Track requests, approvals, pickups and returns here. You’ll also see when a request needs your attention.'],
 ['[data-dashboard-tab="saved"]','שומרים כדי לחזור בקלות','Keep your favourites close','פריטים וגמ״חים ששמרת מחכים כאן, יחד עם החיפושים השמורים שלך.','Find your saved items, gmachs and searches here whenever you need them.'],
 ['#dashboard-add-gmach','רוצה לעזור לאחרים?','Want to help others?','מכאן פותחים גמ״ח. אפשר להשאיל ציוד לאחרים ולהמשיך לשאול פריטים באותו חשבון.','Start a gmach here to lend equipment to others. You can still borrow items using the same account.'],
 ['#add-item-button','הציוד שלך יכול לעזור','Your equipment can help','אחרי פתיחת גמ״ח, הכפתור הזה מאפשר להוסיף פריטים להשאלה ולנהל את הזמינות שלהם.','Once you’ve created a gmach, add items to lend and manage their availability here.'],
 ['#dashboard-account-button','החשבון שלך, בשליטתך','Your account, your preferences','כאן מעדכנים פרטים אישיים ומוצאים את הגדרות החשבון. אפשר להפעיל את הסיור שוב מהכפתור באזור האישי.','Update your personal details and access account settings here. You can replay this tour from your dashboard.'],
 ['#dashboard-view [data-go-home]','מוכנים למצוא את מה שצריך','Ready to find what you need','מכאן חוזרים לקטלוג כדי למצוא ציוד ולבדוק זמינות. כל ההתקדמות שלך נשמרת באזור האישי.','Return to the catalogue to find equipment and check availability. Your requests stay in your account.']
];
async function api(path,init={}){const r=await fetch(path,{credentials:'same-origin',...init});if(!r.ok)throw new Error('Tour state request failed');return r.json()}
function localKey(id){return 'gmach-account-tour-dismissed:'+id}
function cleanup(){if(!active)return;const a=active;active=null;a.abort.abort();a.observer.disconnect();a.resize.disconnect();a.dialog.close();a.dialog.remove();if(visible(a.previousFocus))a.previousFocus.focus({preventScroll:true})}
function save(step,extra={}){return api('/api/me/tours/dashboard',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({step,...extra})})}
function finish(dismissed){if(!active)return;const {index,userId}=active;try{localStorage.setItem(localKey(userId),'1')}catch{}save(index,dismissed?{dismissed:true}:{completed:true}).catch(()=>{});cleanup()}
function position(){if(!active)return;const a=active;if(!visible(document.querySelector('#dashboard-view'))){cleanup();return}const target=document.querySelector(a.steps[a.index][0]);if(!visible(target)){render(Math.min(a.index+1,a.steps.length-1),1);return}
const r=target.getBoundingClientRect(),vw=innerWidth,vh=innerHeight,pad=7;
const x=Math.max(8,r.left-pad),y=Math.max(8,r.top-pad),w=Math.min(vw-8,r.right+pad)-x,h=Math.min(vh-8,r.bottom+pad)-y;
for(const rect of a.dialog.querySelectorAll('[data-tour-hole],[data-tour-outline]')){rect.setAttribute('x',x);rect.setAttribute('y',y);rect.setAttribute('width',Math.max(0,w));rect.setAttribute('height',Math.max(0,h))}
const card=a.card,gap=18,above=y-gap-16,below=vh-y-h-gap-16;card.style.maxHeight=Math.max(140,Math.min(vh-32,Math.max(above,below)))+'px';const cw=card.offsetWidth,ch=card.offsetHeight;
let top=y+h+gap;if(top+ch>vh-16)top=y-ch-gap;if(top<16)top=Math.max(16,Math.min(vh-ch-16,(vh-ch)/2));
const left=Math.max(16,Math.min(vw-cw-16,en()?x:x+w-cw));card.style.top=top+'px';card.style.left=left+'px';card.dataset.side=top>=y+h?'below':'above';
}
function render(index,direction=1){if(!active)return;const a=active;while(index>=0&&index<a.steps.length&&!visible(document.querySelector(a.steps[index][0])))index+=direction;if(index<0||index>=a.steps.length){finish(false);return}a.index=index;const step=a.steps[index];a.dialog.dir=en()?'ltr':'rtl';a.dialog.lang=en()?'en':'he';a.dialog.querySelector('[data-tour-title]').textContent=t(step[1],step[2]);a.dialog.querySelector('[data-tour-description]').textContent=t(step[3],step[4]);a.dialog.querySelector('[data-tour-count]').textContent=t('שלב '+(index+1)+' מתוך '+a.steps.length,'Step '+(index+1)+' of '+a.steps.length);a.dialog.querySelector('[data-tour-progress]').style.width=((index+1)/a.steps.length*100)+'%';a.dialog.querySelector('[data-tour-prev]').hidden=index===0;a.dialog.querySelector('[data-tour-next]').textContent=index===a.steps.length-1?t('יוצאים לדרך','Let’s get started'):t('הבא','Next');a.dialog.querySelector('[data-tour-dots]').replaceChildren(...a.steps.map((_,i)=>{const dot=document.createElement('span');dot.className=i===index?'is-current':i<index?'is-done':'';return dot}));
const target=document.querySelector(step[0]);target.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});position();requestAnimationFrame(()=>{position();if(active===a)a.dialog.querySelector('[data-tour-title]').focus({preventScroll:true})});save(index).catch(()=>{});
}
async function start({manual=false,userId=null}={}){if(active||checking||!visible(document.querySelector('#dashboard-view')))return;checking=true;try{if(document.querySelector('dialog[open]'))return;const me=userId?{user:{id:userId}}:await api('/api/auth/me');if(!me.user)return;userId=me.user.id;
if(!manual){try{if(localStorage.getItem(localKey(userId))==='1'||sessionStorage.getItem('gmach-account-tour-shown:'+userId)==='1')return}catch{}const state=await api('/api/me/tours/dashboard');if(state.tour?.completed_at||state.tour?.dismissed_at)return}
if(!visible(document.querySelector('#dashboard-view'))||document.querySelector('dialog[open]'))return;const available=steps.filter(s=>visible(document.querySelector(s[0])));if(!available.length)return;
try{sessionStorage.setItem('gmach-account-tour-shown:'+userId,'1')}catch{}
const d=document.createElement('dialog');d.id='account-spotlight-tour';d.className='account-spotlight-tour';d.setAttribute('aria-labelledby','account-tour-heading');d.setAttribute('aria-describedby','account-tour-description');
d.innerHTML='<svg class="account-tour-shade" aria-hidden="true" width="100%" height="100%"><defs><mask id="account-tour-mask"><rect width="100%" height="100%" fill="white"/><rect data-tour-hole rx="14" fill="black"/></mask></defs><rect width="100%" height="100%" fill="#102038" fill-opacity=".66" mask="url(#account-tour-mask)"/><rect data-tour-outline rx="14" fill="none" stroke="#dcb477" stroke-width="3"/></svg><section class="account-tour-card"><div class="account-tour-top"><span data-tour-count></span><button type="button" data-tour-close aria-label="'+t('סגירת הסיור','Close tour')+'">×</button></div><div class="account-tour-emblem" aria-hidden="true">✦</div><h2 id="account-tour-heading" data-tour-title tabindex="-1"></h2><p id="account-tour-description" data-tour-description></p><div class="account-tour-dots" data-tour-dots aria-hidden="true"></div><div class="account-tour-progress" aria-hidden="true"><span data-tour-progress></span></div><div class="account-tour-buttons"><button type="button" data-tour-skip>'+t('דלג על הסיור','Skip tour')+'</button><div><button type="button" data-tour-prev>'+t('הקודם','Back')+'</button><button type="button" data-tour-next></button></div></div></section>';
document.body.append(d);const abort=new AbortController(),observer=new MutationObserver(()=>{if(active&&!visible(document.querySelector('#dashboard-view')))cleanup()}),resize=new ResizeObserver(position);active={dialog:d,card:d.querySelector('.account-tour-card'),steps:available,index:0,userId,abort,observer,resize,previousFocus:document.activeElement};
observer.observe(document.querySelector('#dashboard-view'),{attributes:true,attributeFilter:['hidden']});resize.observe(active.card);d.querySelector('[data-tour-next]').onclick=()=>active&&(active.index===active.steps.length-1?finish(false):render(active.index+1));d.querySelector('[data-tour-prev]').onclick=()=>active&&render(active.index-1,-1);d.querySelector('[data-tour-skip]').onclick=()=>finish(true);d.querySelector('[data-tour-close]').onclick=()=>finish(true);d.addEventListener('cancel',e=>{e.preventDefault();finish(true)},{signal:abort.signal});d.addEventListener('keydown',e=>{if(e.key==='Tab'){const b=[...d.querySelectorAll('button')].filter(visible),first=b[0],last=b.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.id==='account-tour-heading')){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},{signal:abort.signal});window.addEventListener('resize',position,{signal:abort.signal});window.addEventListener('scroll',position,{capture:true,signal:abort.signal});window.visualViewport?.addEventListener('resize',position,{signal:abort.signal});d.showModal();render(0);
}catch{cleanup()}finally{checking=false}}
window.GmachStartAccountTour=start;
function install(){const header=document.querySelector('#dashboard-view .dashboard-title-line');if(!header)return;const existing=header.querySelector('[data-account-tour-replay]');if(existing){const label=t('סיור באזור האישי','Account tour');if(existing.textContent!==label)existing.textContent=label;return;}const b=document.createElement('button');b.type='button';b.className='account-tour-replay';b.dataset.accountTourReplay='1';b.textContent=t('סיור באזור האישי','Account tour');b.onclick=()=>start({manual:true});header.append(b)}
const observe=new MutationObserver(install);function init(){observe.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['lang','dir']});install()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
